    File jardir = new File(dir);
    if (jardir.isDirectory()) {
        File[] files = jardir.listFiles();
        if (files != null) {
            for (File file : files) {
                if (file.getName().endsWith(".jar")) {
                    try {
                        cpV.add(file.toURI().toURL());
                    } catch (MalformedURLException e) {
                        e.printStackTrace();
                    }
                }
            }
        }
    }
}

