public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    final byte[] data = schema.toByteArray(message, buffer);
    final int size = data.length;
    ProtobufVarintEncoder.writeRawVarint32(out, size);
    out.write(data);
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    final byte[] data = schema.writeTo(buffer, message);
    final int size = data.length;
    Varint.writeUnsignedVarInt32(size, out);
    out.write(data);
    return size;
}

private static void writeRawVarint32(OutputStream out, int value) throws IOException {
    while ((value & ~0x7F) != 0) {
        out.write((value & 0x7F) | 0x80);
        value >>>= 7;
    }
    out.write(value);
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toByteArray(message, buffer);
    int size = data.length;
    VarInt.writeUnsignedInt(size, out);
    out.write(data);
    return size;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toByteArray(message, buffer);
    int size = ProtobufVarintEncoding.computeRawVarint32Size(data.length);
    ProtobufVarintEncoding.writeRawVarint32(out, data.length);
    out.write(data);
    return size + data.length;
}

