static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Assuming the month is valid and has at least 31 days for simplicity
    int newDay = ((day - 1) / dayStep) * dayStep + 1;

    // Reconstruct the time bucket with the new day
    return year * 10000 + month * 100 + newDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    int dayOfWeek = getDayOfWeek(year, month, day);
    int daysToSubtract = (dayOfWeek - 1 + 7 - dayStep) % 7;
    int newDay = day - daysToSubtract;

    if (newDay <= 0) {
        int[] daysInMonth = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
        if (month == 3) {
            daysInMonth[1] += isLeapYear(year) ? 1 : 0;
        }
        month--;
        if (month == 0) {
            year--;
            month = 12;
        }
        newDay += daysInMonth[month - 1];
    }

    return year * 10000 + month * 100 + newDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int dayOfYear = (int) (timeBucket % 10000);
    int baseDay = dayOfYear - (dayOfYear - 1) % dayStep;
    if (baseDay < 100) {
        return year * 10000 + baseDay;
    } else {
        int month = 1;
        int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) {
            daysInMonth[1] = 29;
        }
        int accumulatedDays = 0;
        while (accumulatedDays + daysInMonth[month - 1] < baseDay) {
            accumulatedDays += daysInMonth[month - 1];
            month++;
        }
        int dayOfMonth = baseDay - accumulatedDays;
        return year * 10000 + month * 100 + dayOfMonth;
    }
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int dayOfYear = (int) (timeBucket % 10000);
    int adjustedDayOfYear = ((dayOfYear - 1) / dayStep) * dayStep + 1;
    return year * 10000L + adjustedDayOfYear;
}

