    int year = (int) (timeBucket / 10000);
    int dayOfYear = (int) (timeBucket % 10000);
    int baseDay = dayOfYear - (dayOfYear - 1) % dayStep;
    if (baseDay < 100) {
        return year * 10000 + baseDay;
    } else {
        return year * 10000 + (baseDay - 100);
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size++;
        } else if (ch < 0x800) {
            size += 2;
        } else if (Character.isSurrogatePair(ch, str.charAt(i + 1))) {
            size += 4;
            i++; // Skip the next char as it's part of the surrogate pair
        } else {
            size += 3;
        }
    }
    return size;
}

