public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    final int len = str.length();
    int size = len * 3;
    LinkedBuffer buffer = ensureUsing(lb, size);

    int pos = 0;
    int i = 0;
    while (i < len) {
        char c = str.charAt(i++);
        if (c < 0x80) {
            buffer.buffer[buffer.offset + pos++] = (byte) c;
        } else if (c < 0x800) {
            buffer.buffer[buffer.offset + pos++] = (byte) (0xc0 | (c >> 6));
            buffer.buffer[buffer.offset + pos++] = (byte) (0x80 | (c & 0x3f));
        } else if (Character.isHighSurrogate(c)) {
            if (i >= len) {
                throw new IllegalArgumentException("Unmatched surrogate pair");
            }
            char low = str.charAt(i++);
            if (!Character.isLowSurrogate(low)) {
                throw new IllegalArgumentException("Unmatched surrogate pair");
            }
            int codePoint = Character.toCodePoint(c, low);
            buffer.buffer[buffer.offset + pos++] = (byte) (0xf0 | (codePoint >> 18));
            buffer.buffer[buffer.offset + pos++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
            buffer.buffer[buffer.offset + pos++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
            buffer.buffer[buffer.offset + pos++] = (byte) (0x80 | (codePoint & 0x3f));
        } else {
            buffer.buffer[buffer.offset + pos++] = (byte) (0xe0 | (c >> 12));
            buffer.buffer[buffer.offset + pos++] = (byte) (0x80 | ((c >> 6) & 0x3f));
            buffer.buffer[buffer.offset + pos++] = (byte) (0x80 | (c & 0x3f));
        }
    }

    buffer.offset += pos;

    buffer.commit(pos);
    return buffer.next == null ? buffer : lb;
}

