        if (c < 0x80) {
            buffer.buffer[offset++] = (byte) c;
        } else if (c < 0x800) {
            buffer.buffer[offset++] = (byte) (0xc0 | (c >> 6));
            buffer.buffer[offset++] = (byte) (0x80 | (c & 0x3f));
        } else if (Character.isSurrogate(c)) {
            char low = str.charAt(++i);
            int codePoint = Character.toCodePoint(c, low);
            buffer.buffer[offset++] = (byte) (0xf0 | (codePoint >> 18));
            buffer.buffer[offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
            buffer.buffer[offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
            buffer.buffer[offset++] = (byte) (0x80 | (codePoint & 0x3f));
        } else {
            buffer.buffer[offset++] = (byte) (0xe0 | (c >> 12));
            buffer.buffer[offset++] = (byte) (0x80 | ((c >> 6) & 0x3f));
            buffer.buffer[offset++] = (byte) (0x80 | (c & 0x3f));
        }
    }

