public static String findAndSubst(String key, Properties props){
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Simple variable substitution logic
    // Assuming variables are in the format ${varName}
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < value.length()) {
        int start = value.indexOf("${", i);
        int end = value.indexOf("}", start + 2);
        if (start != -1 && end != -1) {
            result.append(value.substring(i, start));
            String varName = value.substring(start + 2, end);
            String varValue = props.getProperty(varName);
            if (varValue != null) {
                result.append(varValue);
            } else {
                result.append("${").append(varName).append("}");
            }
            i = end + 1;
        } else {
            result.append(value.substring(i));
            break;
        }
    }
    return result.toString();
}

public static String findAndSubst(String key,Properties props){
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Simple variable substitution logic, assuming variables are in the form ${var}
    StringBuilder result = new StringBuilder();
    int pos = 0;
    while (pos < value.length()) {
        int start = value.indexOf("${", pos);
        if (start == -1) {
            result.append(value.substring(pos));
            break;
        }
        result.append(value.substring(pos, start));
        int end = value.indexOf("}", start);
        if (end == -1) {
            result.append(value.substring(start));
            break;
        }
        String varName = value.substring(start + 2, end);
        String varValue = props.getProperty(varName, "");
        result.append(varValue);
        pos = end + 1;
    }
    return result.toString();
}

public static String findAndSubst(String key, Properties props){
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Simple variable substitution: replace ${var} with the value of var from props
    while (value.contains("${")) {
        int start = value.indexOf("${");
        int end = value.indexOf("}", start);
        if (end == -1) {
            break; // No closing brace found, stop processing
        }
        String varName = value.substring(start + 2, end);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            value = value.substring(0, start) + varValue + value.substring(end + 1);
        } else {
            value = value.substring(0, start) + value.substring(end + 1); // Remove unresolved variable
        }
    }
    return value;
}

public static String findAndSubst(String key, Properties props){
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Perform variable substitution
    // Assuming the substitution format is ${varName}
    return value.replaceAll("\\$\\{([^}]*)\\}", (match) -> {
        String varName = match.group(1);
        String varValue = props.getProperty(varName);
        return varValue != null ? varValue : match.group();
    });
}

public static String findAndSubst(String key,Properties props){
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Assuming variable substitution is done by replacing ${var} with the value of var in props
    StringBuffer sb = new StringBuffer();
    Matcher matcher = Pattern.compile("\\$\\{([^}]*)\\}").matcher(value);
    while (matcher.find()) {
        String var = matcher.group(1);
        String varValue = props.getProperty(var, "");
        matcher.appendReplacement(sb, Matcher.quoteReplacement(varValue));
    }
    matcher.appendTail(sb);
    return sb.toString();
}

