        int type = currentFrame[i];
        if (type == TypeConstants.ITEM_TOP) {
            stackMapTableEntries.add(new VerificationTypeInfo(Opcodes.ITEM_Top));
        } else if (type == TypeConstants.ITEM_INTEGER) {
            stackMapTableEntries.add(new VerificationTypeInfo(Opcodes.ITEM_Integer));
