            stackMapTableEntries.add(new VerificationTypeInfo(Opcodes.ITEM_Float));
        } else if (type == TypeConstants.ITEM_NULL) {
            stackMapTableEntries.add(new VerificationTypeInfo(Opcodes.ITEM_Null));
        } else if (type == TypeConstants.ITEM_UNINITIALIZED_THIS) {
            stackMapTableEntries.add(new VerificationTypeInfo(Opcodes.ITEM_UninitializedThis));
        } else if (type >= TypeConstants.ITEM_OBJECT) {
            stackMapTableEntries.add(new VerificationTypeInfo(Opcodes.ITEM_Object, cp.newClass(currentFrame[i] - TypeConstants.ITEM_OBJECT)));
        } else if (type >= TypeConstants.ITEM_UNINITIALIZED) {
            stackMapTableEntries.add(new VerificationTypeInfo(Opcodes.ITEM_Uninitialized, currentFrame[i] - TypeConstants.ITEM_UNINITIALIZED));
        }
    }
}

