public static String trimTrailingWhitespace(String str){
    if (str == null) {
        return null;
    }
    int len = str.length();
    int st = 0;
    while ((st < len) && Character.isWhitespace(str.charAt(len - 1))) {
        len--;
    }
    return ((st > 0) || (len < str.length())) ? str.substring(0, len) : str;
}

