public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    int i = 0;
    while (i < str.length()) {
        char c = str.charAt(i);
        if (c == '\\') {
            i++;
            if (i >= str.length()) {
                throw new Exception("Invalid escape sequence");
            }
            char next = str.charAt(i);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    if (i + 4 < str.length()) {
                        String hex = str.substring(i + 1, i + 5);
                        try {
                            int codePoint = Integer.parseInt(hex, 16);
                            sb.append((char) codePoint);
                            i += 4;
                        } catch (NumberFormatException e) {
                            throw new Exception("Invalid Unicode escape sequence: \\u" + hex);
                        }
                    } else {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    break;
                default:
                    throw new Exception("Invalid escape sequence: \\" + next);
            }
        } else {
            sb.append(c);
        }
        i++;
    }
    return sb.toString();
}

