private static int hexDigitToValue(char c) throws Exception {
    if ('0' <= c && c <= '9') {
        return c - '0';
    }
    if ('a' <= c && c <= 'f') {
        return c - 'a' + 10;
    }
    if ('A' <= c && c <= 'F') {
        return c - 'A' + 10;
    }
    throw new Exception("Invalid hexadecimal digit: " + c);
}

