public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder output = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char currentChar = str.charAt(i);
        if (currentChar == '\\') {
            if (i + 1 < length) {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case 'b':
                        output.append('\b');
                        i++;
                        break;
                    case 't':
                        output.append('\t');
                        i++;
                        break;
                    case 'n':
                        output.append('\n');
                        i++;
                        break;
                    case 'f':
                        output.append('\f');
                        i++;
                        break;
                    case 'r':
                        output.append('\r');
                        i++;
                        break;
                    case '\"':
                        output.append('\"');
                        i++;
                        break;
                    case '\'':
                        output.append('\'');
                        i++;
                        break;
                    case '\\':
                        output.append('\\');
                        i++;
                        break;
                    default:
                        output.append(currentChar);
                        break;
                }
            } else {
                output.append(currentChar);
            }
        } else {
            output.append(currentChar);
        }
    }
    return output.toString();
}

