protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Assuming GraphPath is an interface and we need to return an implementation like ListenablePath
    // Also assuming V is the vertex type and E is the edge type
    // This is a simple implementation and might need adjustment based on actual GraphPath implementation

    // Create a list to hold the vertices in the order of the tour
    List<V> vertexList = new ArrayList<>();

    // Assuming the graph is connected and Eulerian for the tour to be valid
    // Start from an arbitrary vertex
    if (tour.isEmpty()) {
        return graph.createEmptyPath();
    }

    E startEdge = tour.iterator().next();
    V currentVertex = graph.getEdgeSource(startEdge);
    vertexList.add(currentVertex);

    // Traverse the tour to build the path
    while (!tour.isEmpty()) {
        E currentEdge = null;
        for (E edge : tour) {
            if (graph.getEdgeSource(edge).equals(currentVertex) || graph.getEdgeTarget(edge).equals(currentVertex)) {
                currentEdge = edge;
                break;
            }
        }

        if (currentEdge == null) {
            throw new IllegalArgumentException("The provided set of edges does not form a valid tour.");
        }

        // Add the target vertex of the current edge to the path
        V targetVertex = graph.getEdgeSource(currentEdge).equals(currentVertex) ? graph.getEdgeTarget(currentEdge) : graph.getEdgeSource(currentEdge);
        vertexList.add(targetVertex);

        // Remove the used edge from the tour set
        tour.remove(currentEdge);

        // Move to the next vertex
        currentVertex = targetVertex;
    }

    // Create and return the path
    return graph.getPath(vertexList.get(0), vertexList.get(vertexList.size() - 1), vertexList, new ArrayList<>(tour));
}

