public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path must not be null");
    }

    // Normalize the paths by replacing backslashes with forward slashes
    path = path.replace('\\', '/');
    relativePath = relativePath.replace('\\', '/');

    // Handle relative path components
    String[] pathComponents = path.split("/");
    String[] relativeComponents = relativePath.split("/");

    int pathIndex = pathComponents.length - 1;

    for (String component : relativeComponents) {
        if (component.equals("..")) {
            if (pathIndex > 0) {
                pathIndex--; // Move up one directory
            }
        } else if (!component.equals(".")) {
            // Add component to the path
            pathComponents[++pathIndex] = component;
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    for (int i = 0; i <= pathIndex; i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(pathComponents[i]);
    }

    return result.toString();
}

