            // Move up one directory
            int lastSlashIndex = resultPath.lastIndexOf("/");
            if (lastSlashIndex != -1) {
                resultPath.setLength(lastSlashIndex);
            }
        } else if (!part.equals(".")) {
            // Append the directory or file name
            resultPath.append(part).append("/");
        }
    }

    // Remove the trailing "/"
    if (resultPath.length() > 0 && resultPath.charAt(resultPath.length() - 1) == '/') {
        resultPath.setLength(resultPath.length() - 1);
    }

    return resultPath.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }

    // Normalize the paths by removing trailing slashes
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Process each component of the relative path
    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            // Move up one directory if possible
            if (pathComponents.length > 0) {
                pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
            }
        } else if (component.equals(".")) {
            // Current directory, do nothing
            continue;
        } else {
            // Add the component to the path
            String[] newPathComponents = new String[pathComponents.length + 1];
            System.arraycopy(pathComponents, 0, newPathComponents, 0, pathComponents.length);
            newPathComponents[pathComponents.length] = component;
            pathComponents = newPathComponents;
        }
    }

    // Join the components back into a single path
    return String.join("/", pathComponents);
}

public static String applyRelativePath(String path, String relativePath) {
    // Normalize the paths by removing any trailing slashes
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Split the paths into segments
    String[] pathSegments = path.split("/");
    String[] relativePathSegments = relativePath.split("/");

    // Use a stack to resolve the relative path
    Stack<String> pathStack = new Stack<>();
    for (String segment : pathSegments) {
        pathStack.push(segment);
    }

    for (String segment : relativePathSegments) {
        if (segment.equals("..")) {
            if (!pathStack.isEmpty()) {
                pathStack.pop(); // Move up one directory
            }
        } else if (!segment.equals(".")) {
            pathStack.push(segment); // Move down into a directory
        }
    }

    // Build the final path
    StringBuilder result = new StringBuilder();
    while (!pathStack.isEmpty()) {
        result.insert(0, pathStack.pop());
        if (!pathStack.isEmpty()) {
            result.insert(0, "/");
        }
    }

    return result.toString();
}

